def count_valid_subsets(N, S):
    MOD = 10**9 + 7

    # Memoization dictionary
    memo = {}

    def dp(index, remainder, is_tight):
        if index == N:
            return 1 if remainder == 0 else 0

        if (index, remainder, is_tight) in memo:
            return memo[(index, remainder, is_tight)]

        limit = int(S[index]) if is_tight else 9
        count = 0

        for digit in range(0, limit + 1):
            count += dp(index + 1, (remainder * 10 + digit) % 3, is_tight and (digit == limit))
            count %= MOD

        memo[(index, remainder, is_tight)] = count
        return count

    # Start the recursion
    return dp(0, 0, True)

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    S = data[1]
    print(count_valid_subsets(N, S))
